// ── Conference icons ──────────────────────────────────────────────────
//
// Inline SVGs that paint with `currentColor`, so an icon inherits the color of
// the text it sits beside. Generated from the source files in
// public/conferences/2026/assets/icons/ (which remain, for OG images and any
// non-React use).
//
// These replace 13 hand-written <img> tags, each with its own
// eslint-disable and a hardcoded width/height pair.
//
// ⚠️ Why this matters beyond tidiness: as <img> files, the only way to tint an
//    icon was the CSS filter `grayscale(1) brightness(0.4)`, duplicated under
//    three different constant names. That filter is a no-op on a black source
//    — brightness scales RGB, and black × 0.4 is still black — so the icons
//    rendered #000 while the comment claimed gray-110 (#50555A) and the labels
//    beside them really were #50555A. currentColor removes the hack and the
//    mismatch together.
//
// See docs/CONFERENCE-DESIGN-SYSTEM.md Phase 3.

interface IconProps {
  /** Rendered square size in px (default 20). */
  size?: number;
  className?: string;
  style?: React.CSSProperties;
}

